function greetingFor(s,name,date=sydneyDate(),hour=new Date().getHours(),weather=null){const en=typeof appLanguage!=='undefined'&&appLanguage==='en',salute=hour<11?(en?'Good morning':'Chào buổi sáng'):hour<17?(en?'Hello':'Chào buổi chiều'):(en?'Good evening':'Chào buổi tối'),w=s.weeks?.[monday(date)],count=w?.days?.[date]?.dinner?.recipes?.length||0;let message=en?(count?`Dinner has ${count} dishes planned. A little prep now can make tonight easier.`:'Shall we choose something simple for dinner?'):(count?`Tối nay đã có ${count} món. Chuẩn bị một chút để đến bữa nhẹ nhàng hơn nhé.`:'Mình chọn một bữa tối đơn giản nhé?');if(weather?.date===date&&Number.isFinite(weather.temp)){if(weather.temp>=30)message=weather.source==='live'?(en?'It’s warm in your selected city. Fancy a light meal or a cool fruit dessert?':'Thành phố bạn chọn đang nóng. Nhà mình thử món nhẹ hoặc trái cây mát nhé?'):(en?'You marked today as hot. Fancy a light meal or a cool fruit dessert?':'Hôm nay bạn đánh dấu trời nóng. Nhà mình thử món nhẹ hoặc trái cây mát nhé?');else if(weather.temp<=18)message=weather.source==='live'?(en?'It’s cool in your selected city. A warm soup might be lovely.':'Thành phố bạn chọn đang mát. Một món canh nóng có vẻ hợp đấy.'):(en?'You marked today as cool. A warm soup might be lovely.':'Hôm nay bạn đánh dấu trời mát. Một món canh nóng có vẻ hợp đấy.')}return{title:salute+(name?', '+name:''),message}}
